def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, remaining_qty)
    sell_book = []  # list of (price, arrival_time, id, remaining_qty)
    order_map = {}  # id -> (side, price, arrival_time, index_in_book)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, arr_time, book_index = order_map[order_id]
                if side == 'buy':
                    if book_index < len(buy_book) and buy_book[book_index][2] == order_id:
                        buy_book.pop(book_index)
                        for i in range(book_index, len(buy_book)):
                            oid = buy_book[i][2]
                            order_map[oid] = (order_map[oid][0], order_map[oid][1], order_map[oid][2], i)
                else:
                    if book_index < len(sell_book) and sell_book[book_index][2] == order_id:
                        sell_book.pop(book_index)
                        for i in range(book_index, len(sell_book)):
                            oid = sell_book[i][2]
                            order_map[oid] = (order_map[oid][0], order_map[oid][1], order_map[oid][2], i)
                del order_map[order_id]

        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            if side == 'buy':
                remaining = qty
                matched_indices = []

                for i, (sell_price, sell_time, sell_id, sell_qty) in enumerate(sell_book):
                    if remaining == 0:
                        break
                    if order_type == 'market' or sell_price <= price:
                        trade_qty = min(remaining, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining -= trade_qty
                        matched_indices.append((i, trade_qty))

                for idx, trade_qty in reversed(matched_indices):
                    sell_price, sell_time, sell_id, sell_qty = sell_book[idx]
                    new_qty = sell_qty - trade_qty
                    if new_qty == 0:
                        sell_book.pop(idx)
                        for i in range(idx, len(sell_book)):
                            oid = sell_book[i][2]
                            order_map[oid] = (order_map[oid][0], order_map[oid][1], order_map[oid][2], i)
                        del order_map[sell_id]
                    else:
                        sell_book[idx] = (sell_price, sell_time, sell_id, new_qty)

                if order_type == 'limit' and remaining > 0:
                    buy_book.append((price, arrival_time, order_id, remaining))
                    order_map[order_id] = ('buy', price, arrival_time, len(buy_book) - 1)
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    for i, (p, t, oid, q) in enumerate(buy_book):
                        order_map[oid] = (order_map[oid][0], order_map[oid][1], order_map[oid][2], i)

            else:  # sell
                remaining = qty
                matched_indices = []

                for i, (buy_price, buy_time, buy_id, buy_qty) in enumerate(buy_book):
                    if remaining == 0:
                        break
                    if order_type == 'market' or buy_price >= price:
                        trade_qty = min(remaining, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining -= trade_qty
                        matched_indices.append((i, trade_qty))

                for idx, trade_qty in reversed(matched_indices):
                    buy_price, buy_time, buy_id, buy_qty = buy_book[idx]
                    new_qty = buy_qty - trade_qty
                    if new_qty == 0:
                        buy_book.pop(idx)
                        for i in range(idx, len(buy_book)):
                            oid = buy_book[i][2]
                            order_map[oid] = (order_map[oid][0], order_map[oid][1], order_map[oid][2], i)
                        del order_map[buy_id]
                    else:
                        buy_book[idx] = (buy_price, buy_time, buy_id, new_qty)

                if order_type == 'limit' and remaining > 0:
                    sell_book.append((price, arrival_time, order_id, remaining))
                    order_map[order_id] = ('sell', price, arrival_time, len(sell_book) - 1)
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    for i, (p, t, oid, q) in enumerate(sell_book):
                        order_map[oid] = (order_map[oid][0], order_map[oid][1], order_map[oid][2], i)

        arrival_time += 1

    return trades

